            ReleaseOrder order = releaseRepository.findByIdForUpdate(releaseId)
                    .orElseThrow(() -> ApiException.notFound("RELEASE_NOT_FOUND", "发布单不存在: " + releaseId));
            if (order.status() == ReleaseStatus.CANCELLED) {
                throw ApiException.conflict("RELEASE_CANCELLED", "发布单已取消，不能恢复");
            }
            if (order.status() != ReleaseStatus.PAUSED) {
                throw ApiException.conflict("RELEASE_NOT_PAUSED",
                        "发布单状态为 " + order.status() + "，仅 PAUSED 可恢复");
            }
            if (order.version() != request.expectedVersion()) {
                throw ApiException.conflict("VERSION_CONFLICT",
                        "expectedVersion 与当前版本不一致: " + order.version());
            }
            releaseRepository.resume(releaseId, request.expectedVersion());
            ReleaseOrder resumed = findOrder(releaseId);
            resumeRecordRepository.insert(releaseId, resumed.monitorRound(), request.reason(),
                    Instant.now(clock).toString());
            return ReleaseView.of(resumed);
        }, ReleaseView.class);
    }

    public ReleaseView cancel(long releaseId, String requestId) {
        String fingerprint = String.join("|", "release.cancel", String.valueOf(releaseId));
        return idempotency.execute(requestId, "release.cancel", fingerprint, () -> {
            ReleaseOrder order = releaseRepository.findByIdForUpdate(releaseId)
                    .orElseThrow(() -> ApiException.notFound("RELEASE_NOT_FOUND", "发布单不存在: " + releaseId));
            if (order.status() == ReleaseStatus.ACTIVE || order.status() == ReleaseStatus.PAUSED) {
                releaseRepository.cancel(releaseId);
                taskRepository.cancelPendingByRelease(releaseId);
            }
            return ReleaseView.of(findOrder(releaseId));
        }, ReleaseView.class);
    }

    /**
     * 当前监控轮次统计（只读，不触发状态变化）。
     */
    public MonitorView monitor(long releaseId) {
        return MonitorView.of(findOrder(releaseId));
    }

    /**
     * 暂停/恢复历史（只读，不触发状态变化）。
     */
    public ReleaseHistoryResponse history(long releaseId) {
        findOrder(releaseId);
        var pauses = pauseRecordRepository.findByRelease(releaseId).stream()
                .map(PauseRecordView::of).toList();
        var resumes = resumeRecordRepository.findByRelease(releaseId).stream()
                .map(ResumeRecordView::of).toList();
        return new ReleaseHistoryResponse(releaseId, pauses, resumes);
    }

    public ReleaseOrder findOrder(long releaseId) {
        return releaseRepository.findById(releaseId)
                .orElseThrow(() -> ApiException.notFound("RELEASE_NOT_FOUND", "发布单不存在: " + releaseId));
    }
}
package com.example.starter.firmware.service;

import com.example.starter.firmware.error.ApiException;
import com.example.starter.firmware.repo.IdempotencyRepository;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;

import java.util.function.Supplier;

/**
 * 写操作幂等执行器：同一事务内完成业务变更与去重记录写入，原子提交。
 * 同键同参重放原成功结果；同键异参返回 409；业务失败回滚，不占键。
 * 同 requestId 的执行通过分段锁串行化，避免并发下检查与写入之间的竞态；
 * 数据库唯一约束作为最终兜底。
 */
@Service
public class IdempotencyService {

    /**
     * 内部信号：并发下同键插入冲突，回滚当前事务后改为重放已提交记录。
     */
    private static final class ReplayNeededException extends RuntimeException {
    }

    private static final int LOCK_STRIPES = 256;

    private final Object[] locks = new Object[LOCK_STRIPES];

    private final IdempotencyRepository repository;
    private final TransactionTemplate transactionTemplate;
    private final ObjectMapper objectMapper;

    public IdempotencyService(IdempotencyRepository repository, TransactionTemplate transactionTemplate,
                              ObjectMapper objectMapper) {
        this.repository = repository;
        this.transactionTemplate = transactionTemplate;
        this.objectMapper = objectMapper;
        for (int i = 0; i < LOCK_STRIPES; i++) {
            locks[i] = new Object();
        }
    }

    public <T> T execute(String requestId, String api, String fingerprint, Supplier<T> action, Class<T> type) {
        synchronized (locks[Math.floorMod(requestId.hashCode(), LOCK_STRIPES)]) {
            try {
                return transactionTemplate.execute(status -> executeInTransaction(requestId, api, fingerprint, action, type));
            } catch (ReplayNeededException e) {
                return replayCommitted(requestId, fingerprint, type);
            }
        }
    }

    private <T> T executeInTransaction(String requestId, String api, String fingerprint,
                                       Supplier<T> action, Class<T> type) {
        var existing = repository.find(requestId);
        if (existing.isPresent()) {
            return replay(existing.get(), fingerprint, type);
        }
        T result = action.get();
        try {
            repository.insert(requestId, api, fingerprint, writeJson(result));
        } catch (DuplicateKeyException e) {
            throw new ReplayNeededException();
        }
        return result;
    }

    private <T> T replayCommitted(String requestId, String fingerprint, Class<T> type) {
        var record = repository.find(requestId)
                .orElseThrow(() -> new IllegalStateException("幂等记录缺失: " + requestId));
        return replay(record, fingerprint, type);
    }

    private <T> T replay(IdempotencyRepository.IdempotencyRecord record, String fingerprint, Class<T> type) {
        if (!record.fingerprint().equals(fingerprint)) {
            throw ApiException.conflict("REQUEST_ID_CONFLICT", "requestId 已被不同参数的请求占用");
        }
        try {
            return objectMapper.readValue(record.responseBody(), type);
        } catch (Exception e) {
            throw new IllegalStateException("幂等响应反序列化失败", e);
        }
    }

    private String writeJson(Object value) {
        try {
            return objectMapper.writeValueAsString(value);
        } catch (Exception e) {
            throw new IllegalStateException("幂等响应序列化失败", e);
        }
    }
}

