                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.code").value("RATIO_DECREASE"));

        // 比例越界：400
        mockMvc.perform(post("/api/releases/" + releaseId + "/expand").contentType("application/json").content("""
                        {"requestId":"r5","expectedVersion":2,"ratio":101}
