        mockMvc.perform(get("/api/releases/" + releaseId + "/tasks"))
                .andExpect(jsonPath("$.tasks[0].status").value("CANCELLED"));

        // 取消任务的后到回执：409 且设备版本不更新
        mockMvc.perform(post("/api/tasks/" + taskId + "/receipt").contentType("application/json")
